const categoriasValidas = ['CONSULTA_PRODUCTO', 'ENVIO_CORREO', 'ESCALAMIENTO_HUMANO'];
let categoria = 'ESCALAMIENTO_HUMANO';

try {
  const texto = ($input.item.json.output || '')
    .trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```\s*$/i, '');

  const parsed = JSON.parse(texto);
  if (categoriasValidas.includes(parsed.categoria)) {
    categoria = parsed.categoria;
  }
} catch (e) {
  categoria = 'ESCALAMIENTO_HUMANO';
}

return {
  json: {
    categoria,
    consulta: $('Limpiar Payload').item.json.consulta,
    email: $('Limpiar Payload').item.json.email,
    contexto_memoria: $('Edit Fields1').isExecuted ? $('Edit Fields1').item.json.contexto_memoria : $('Edit Fields2').item.json.contexto_memoria
  }
};

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.myNewField = 1;
}

return $input.all();

